INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 31, 'theory', 'Quiz: diagnostics');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 0, 'What does the load average count in Linux?', '["Only the percent of busy CPU", "Tasks queued for a CPU and in uninterruptible sleep (usually waiting for a disk)", "Only processes reading or writing a disk", "The number of threads in sleep"]', 1, 'Per the proc manual, the load is the number of tasks in the run queue (R) or waiting for disk (D). That is why it can be high while the CPU idles.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 1, 'Which /proc/meminfo field best estimates the memory available to new programs without swapping?', '["MemFree", "Cached", "Buffers", "MemAvailable"]', 3, 'MemAvailable (since kernel 3.14) accounts for the file cache and reclaimable slabs. MemFree understates what is available because the kernel keeps the rest as cache.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 2, 'What does the first line of vmstat 1 output mean?', '["Averages since boot for the per-second rates and the CPU percentages", "A measurement over the last second", "Daily maxima", "Values for the first core only"]', 0, 'In the first line the queue r and memory are instantaneous, while rates and percentages are averaged since boot. So the diagnosis comes from the later lines.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 3, 'Inside a virtual machine top shows st around 20 percent. What does it mean?', '["Guest processes used 20 percent of the CPU", "The guest''s disk is overloaded", "The hypervisor gave the CPU to other machines while the vCPU waited, so the host is overcommitted", "The guest is short of memory"]', 2, 'Steal is time when a virtual CPU was ready to run but got no physical CPU. The cure is on the host: reduce overcommit or move machines.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 4, 'Why does %util near 100 in iostat -x not always prove that an NVMe disk is saturated?', '["Because %util counts only writes", "Because it only says that requests were in flight almost all the time, while the device serves them in parallel", "Because %util is not computed for NVMe", "Because it is averaged since boot"]', 1, '%util is the share of time requests were issued to the device. For parallel devices it does not reflect the limit, so look at the await and aqu-sz.');
